import { describe, it, expect, vi, afterEach } from 'vitest'
import { useBooks } from './useBooks'
import * as api from '../api'

describe('useBooks', () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('starts in loading state before getBooks resolves', () => {
    // Stall resolution so we can observe the initial state
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(() => {}))
    const { result } = renderHook(() => useBooks())
    expect(result.current.loading).toBe(true)
    expect(result.current.data).toBeUndefined()
    expect(result.current.error).toBeUndefined()
  })

  it('transitions loading to false after getBooks resolves', async () => {
    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.error).toBeUndefined()
  })

  it('populates data with the value returned by getBooks', async () => {
    const fakeBooks = [
      { id: '1', title: 'Refactoring', author: 'Fowler' },
      { id: '2', title: 'Clean Code', author: 'Martin' },
    ]
    vi.spyOn(api, 'getBooks').mockResolvedValue(fakeBooks)

    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(result.current.data).toEqual(fakeBooks)
    expect(result.current.error).toBeUndefined()
  })

  it('sets error and clears data when getBooks rejects', async () => {
    const err = new Error('unexpected failure')
    vi.spyOn(api, 'getBooks').mockRejectedValue(err)

    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(result.current.error).toBe(err)
    expect(result.current.data).toBeUndefined()
  })

  it('returns an empty array (not undefined) when getBooks resolves with []', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue([])

    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(result.current.data).toEqual([])
    expect(result.current.error).toBeUndefined()
  })

  it('calls getBooks exactly once on mount', async () => {
    const spy = vi.spyOn(api, 'getBooks')

    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))

    expect(spy).toHaveBeenCalledTimes(1)
  })

  it('does not call getBooks again on re-render', async () => {
